+// Kitchen sites: each location belongs to a site.
+import { AppError } from "../errors.js";
+
+/** Throws unknown_site if `site` is not in the store. */
+export function validateSite(store, site) {
+  if (!(store.data.sites ?? []).some((s) => s.id === site)) throw new AppError("unknown_site", { id: site });
+}
+
+/** Set of location ids belonging to `site`, or null when `site` is omitted. */
+export function siteLocationIds(store, site) {
